app.post('/api/video/submit',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;if(s.authProvider!=='google')return res.status(403).json({error:'Sign in with Google to use Creator video tools.'});try{const i=z.object({prompt:z.string().trim().min(3).max(4000),key:z.string().min(20).max(500),provider:z.enum(['gemini','runway','luma','kling','replicate']).default('gemini'),model:z.string().min(1).max(180),operationId:z.string().min(16).max(100),options:z.object({aspectRatio:z.enum(['16:9','9:16']).optional()}).optional()}).parse(req.body);const job=await reserveMediaJob({userId:s.user.id,provider:i.provider,model:i.model,operationId:i.operationId});if(job.upstreamId){res.setHeader('Cache-Control','no-store');return res.status(202).json({ok:true,jobId:job.id,state:job.state,provider:i.provider,duplicate:true,creditsCharged:0})}if(job.state==='failed'||job.state==='cancelled')throw Object.assign(new Error(job.error||'This video submission did not complete. Start a new operation.'),{status:409});if(job.duplicate){res.setHeader('Cache-Control','no-store');return res.status(202).json({ok:true,jobId:job.id,state:'submitting',duplicate:true,creditsCharged:0})}const keyFingerprint=crypto.createHash('sha256').update(i.key).digest('hex').slice(0,24),healthKey=providerHealthKey(i.provider,i.model,'',keyFingerprint),started=Date.now();if(!await providerAvailablePersistent(healthKey)){await updateMediaJob(job.id,s.user.id,{state:'failed',error:'Provider circuit is open. Start a new operation after the cooldown.'});throw Object.assign(new Error('This video provider is temporarily cooling down after repeated failures. Try another agent or wait one minute.'),{status:503})}try{const upstream=await submitVideo(i);await recordProviderSuccessPersistent(healthKey,Date.now()-started);const attached=await attachMediaJobTask(job.id,s.user.id,{upstreamId:upstream.upstreamId,state:upstream.state});if(attached.state==='cancelled')await cancelVideoJob({provider:i.provider,key:i.key,upstreamId:upstream.upstreamId});res.setHeader('Cache-Control','no-store');return res.status(202).json({ok:true,jobId:job.id,state:attached.state,provider:i.provider,creditsCharged:0,message:attached.state==='cancelled'?'Video submission was cancelled; no credits are charged.':'Video job accepted. It is stored durably; credits are charged only after successful delivery.'})}catch(providerError){if(![400,401,403,404,422].includes(Number(providerError.status)))await recordProviderFailurePersistent(healthKey);await updateMediaJob(job.id,s.user.id,{state:'failed',error:redactSecrets(providerError.message)});throw providerError}}catch(e){err(res,e,e instanceof z.ZodError?422:e.status||400)}});
app.post('/api/video/status',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;if(s.authProvider!=='google')return res.status(403).json({error:'Sign in with Google to use Creator video tools.'});try{const i=z.object({jobId:z.string().min(20).max(100),key:z.string().min(20).max(500)}).parse(req.body);const job=await getMediaJob(i.jobId,s.user.id);if(['failed','cancelled'].includes(job.state)){res.setHeader('Cache-Control','no-store');return res.json({ok:true,state:job.state,progress:job.progress||0,error:job.error||''})}if(!job.upstreamId){if(Date.now()-Number(job.createdAt)>120000){await updateMediaJob(job.id,s.user.id,{state:'failed',error:'Provider submission was interrupted before its task ID was saved. Start a new operation; no Pothub credits were charged.'});return res.json({ok:true,state:'failed',progress:0,error:'Provider submission was interrupted. Start a new operation.'})}res.setHeader('Cache-Control','no-store');return res.json({ok:true,state:'submitting',progress:0,provider:job.provider})}const keyFingerprint=crypto.createHash('sha256').update(i.key).digest('hex').slice(0,24),healthKey=providerHealthKey(job.provider,job.model,'',keyFingerprint),started=Date.now();let result;try{result=await pollVideo({provider:job.provider,key:i.key,model:job.model,upstreamId:job.upstreamId});await recordProviderSuccessPersistent(healthKey,Date.now()-started)}catch(providerError){if(![400,401,403,404,422].includes(Number(providerError.status)))await recordProviderFailurePersistent(healthKey);throw providerError}await updateMediaJob(job.id,s.user.id,{state:result.state,progress:result.progress,error:result.error||'',readyAt:result.state==='ready'?Date.now():null});res.setHeader('Cache-Control','no-store');res.json({ok:true,state:result.state,progress:result.progress,provider:job.provider,error:result.error||undefined});}catch(e){err(res,e,e instanceof z.ZodError?422:e.status||400)}});
app.post('/api/video/result',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;if(s.authProvider!=='google')return res.status(403).json({error:'Sign in with Google to use Creator video tools.'});let deliveryOperationId='',deliveryPayloadHash='',deliveryOperationAcquired=false,deliveryReservationRef='',deliveryReserved=false,deliverySettlement=null;try{const i=z.object({jobId:z.string().min(20).max(100),key:z.string().min(20).max(500)}).parse(req.body);const job=await getMediaJob(i.jobId,s.user.id);if(!job.upstreamId)throw Error('Video provider submission is still being created. Retry shortly.');const status=await pollVideo({provider:job.provider,key:i.key,model:job.model,upstreamId:job.upstreamId});if(status.state!=='ready')throw Error('Video is not ready yet.');await updateMediaJob(job.id,s.user.id,{state:'ready',progress:100,readyAt:Date.now()});const reservationRef=`video-delivery:${job.id}`;deliveryReservationRef=reservationRef;deliveryOperationId=`video-delivery-${job.id}`;deliveryPayloadHash=crypto.createHash('sha256').update(`${s.user.id}:${job.id}:${job.provider}:${job.model}`).digest('hex');const deliveryOperation=await beginOperation(s.user.id,deliveryOperationId,deliveryPayloadHash,{ttlMs:20*60*1000});deliveryOperationAcquired=deliveryOperation.state!=='succeeded';const asset=await fetchVideoAsset({provider:job.provider,key:i.key,model:job.model,upstreamId:job.upstreamId});const maxVideoBytes=Math.max(1024*1024,Math.min(150*1024*1024,Number(process.env.POTHUB_VIDEO_MAX_BYTES)||80*1024*1024));if((asset.length&&asset.length>maxVideoBytes)||(Buffer.isBuffer(asset.body)&&asset.body.length>maxVideoBytes))throw Error('Video exceeds the configured delivery limit.');const charge=await reserveCredits(s.user.id,Math.max(1,BYO_SERVICE_FEES.creator),reservationRef,'Delivered video generation',{jobId:job.id,provider:job.provider,model:job.model});deliveryReserved=true;let settled=false;const settle=async delivered=>{if(settled)return;settled=true;try{if(delivered){await commitCreditReservation(s.user.id,reservationRef);await updateMediaJob(job.id,s.user.id,{state:'delivered',deliveredAt:Date.now()});if(deliveryOperationAcquired)await finishOperation(s.user.id,deliveryOperationId,deliveryPayloadHash,{jobId:job.id,state:'delivered'})}else{await releaseCreditReservation(s.user.id,reservationRef);if(deliveryOperationAcquired)await failOperation(s.user.id,deliveryOperationId,deliveryPayloadHash,'Video delivery stream was interrupted')}}catch(e){console.error('[Pothub video settlement]',redactSecrets(e.message))}};deliverySettlement=settle;res.once('finish',()=>settle(true));res.once('close',()=>{if(!res.writableFinished)settle(false)});res.status(200);res.setHeader('Cache-Control','no-store, private');res.setHeader('Content-Type',asset.mime);res.setHeader('Content-Disposition',`attachment; filename="pothub-video-${job.id.slice(-12)}.${asset.mime==='video/webm'?'webm':'mp4'}"`);res.setHeader('X-Pothub-Credits-Remaining',String(charge.credits));res.setHeader('X-Pothub-Credits-Charged',String(charge.duplicate?0:Math.max(1,BYO_SERVICE_FEES.creator)));res.setHeader('Access-Control-Expose-Headers','X-Request-Id, X-Pothub-Credits-Remaining, X-Pothub-Credits-Charged, Content-Type, Content-Length');if(asset.length)res.setHeader('Content-Length',String(asset.length));if(Buffer.isBuffer(asset.body)){Readable.from([asset.body]).pipe(res);return}const {Readable}=await import('node:stream');let received=0;const stream=Readable.fromWeb(asset.body);stream.on('data',chunk=>{received+=chunk.length;if(received>maxVideoBytes){stream.destroy(new Error('Video exceeds the configured delivery limit.'));settle(false)}});stream.on('error',()=>{settle(false);if(!res.headersSent)res.status(502);res.destroy()});stream.pipe(res);}catch(e){if(deliverySettlement)await deliverySettlement(false);else{if(deliveryReserved&&deliveryReservationRef)await releaseCreditReservation(s.user.id,deliveryReservationRef).catch(()=>{});if(deliveryOperationAcquired&&deliveryOperationId&&deliveryPayloadHash)await failOperation(s.user.id,deliveryOperationId,deliveryPayloadHash,e?.message||'Video delivery failed').catch(()=>{})}if(!res.headersSent)err(res,e,e instanceof z.ZodError?422:/not enough credits|insufficient credits/i.test(String(e?.message||''))?402:e.status||400);else res.destroy()}});
app.post('/api/video/cancel',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;if(s.authProvider!=='google')return res.status(403).json({error:'Sign in with Google to use Creator video tools.'});try{const i=z.object({jobId:z.string().min(20).max(100),key:z.string().min(20).max(500)}).parse(req.body);const job=await getMediaJob(i.jobId,s.user.id);const cancelled=job.upstreamId?await cancelVideoJob({provider:job.provider,key:i.key,upstreamId:job.upstreamId}):true;await updateMediaJob(job.id,s.user.id,{state:'cancelled',cancelledAt:Date.now()});res.json({ok:true,state:'cancelled',providerCancelled:cancelled,message:cancelled?'Provider cancellation requested.':'Polling cancelled locally; the provider may continue processing. No credits are charged unless a result is delivered.'})}catch(e){err(res,e,e instanceof z.ZodError?422:e.status||400)}});
